#include <stdint.h>

/* The probes are the architecture's; a symbol is the object format's. */
#if defined(__APPLE__)
#define OBJECT_NAME(name) "_" name
#else
#define OBJECT_NAME(name) name
#endif

struct large {
    uint8_t bytes[8199];
    uint64_t marker;
};

int64_t r450_step(int64_t x)
{
    /* Force every volatile GP bank to be unavailable across this call. */
#if defined(__aarch64__)
    __asm__ volatile ("" : : :
        "x0", "x1", "x2", "x3", "x4", "x5",
        "x6", "x7", "x8", "x9", "x10", "x11",
        "x12", "x13", "x14", "x15", "x16", "x17",
        "v0", "v1", "v2", "v3", "v4", "v5",
        "v6", "v7", "v16", "v17", "v18", "v19",
        "v20", "v21", "v22", "v23", "v24", "v25",
        "v26", "v27", "v28", "v29", "v30", "v31",
        "cc", "memory");
#elif defined(__riscv)
    __asm__ volatile ("" : : : "a0", "a1", "a2", "a3", "a4", "a5", "a6", "a7", "t0", "t1", "t2", "t3", "t4", "t5", "t6", "fa0", "fa1", "fa2", "fa3", "fa4", "fa5", "fa6", "fa7", "ft0", "ft1", "ft2", "ft3", "ft4", "ft5", "ft6", "ft7", "ft8", "ft9", "ft10", "ft11", "memory");
#else
    __asm__ volatile ("" : : : "rax", "rcx", "rdx", "rsi", "rdi",
                      "r8", "r9", "r10", "r11", "cc", "memory");
#endif
    return x + 1;
}

struct large r450_large(struct large value)
{
    value.bytes[0] += 1;
    value.bytes[4095] += 1;
    value.bytes[8198] += 1;
    value.marker += 1;
    return value;
}

